package org.pyapp.demo

import android.app.Service
import android.content.Intent
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.PixelFormat
import android.os.IBinder
import android.view.Gravity
import android.view.MotionEvent
import android.view.View
import android.view.WindowManager

class OverlayService : Service() {

    private lateinit var windowManager: WindowManager
        private lateinit var overlayView: View

            override fun onBind(intent: Intent?): IBinder? = null

                override fun onCreate() {
                        super.onCreate()
                                windowManager = getSystemService(WINDOW_SERVICE) as WindowManager

                                        // បង្កើតផ្ទាំងគូរ (Transparent Canvas)
                                                overlayView = object : View(this) {
                                                            private val paint = Paint().apply {
                                                                            color = Color.RED // ពណ៌ក្រហម
                                                                                            strokeWidth = 10f // កម្រាស់ខ្សែ
                                                                                                            style = Paint.Style.STROKE
                                                                                                                        }

                                                                                                                                    // ទីតាំងចាប់ផ្តើម និងបញ្ចប់នៃខ្សែ
                                                                                                                                                private var startX = 200f
                                                                                                                                                            private var startY = 500f
                                                                                                                                                                        private var endX = 600f
                                                                                                                                                                                    private var endY = 1000f

                                                                                                                                                                                                override fun onDraw(canvas: Canvas) {
                                                                                                                                                                                                                super.onDraw(canvas)
                                                                                                                                                                                                                                // គូរខ្សែ
                                                                                                                                                                                                                                                canvas.drawLine(startX, startY, endX, endY, paint)
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                        // អនុញ្ញាតឱ្យអូសខ្សែបាន (សម្រាប់ការតេស្ត)
                                                                                                                                                                                                                                                                                    override fun onTouchEvent(event: MotionEvent): Boolean {
                                                                                                                                                                                                                                                                                                    when (event.action) {
                                                                                                                                                                                                                                                                                                                        MotionEvent.ACTION_DOWN -> {
                                                                                                                                                                                                                                                                                                                                                startX = event.x
                                                                                                                                                                                                                                                                                                                                                                        startY = event.y
                                                                                                                                                                                                                                                                                                                                                                                                invalidate()
                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                        MotionEvent.ACTION_MOVE -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                endX = event.x
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        endY = event.y
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                invalidate()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // កំណត់ទម្រង់បង្អួច (Window Parameters)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        val params = WindowManager.LayoutParams(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    WindowManager.LayoutParams.MATCH_PARENT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                WindowManager.LayoutParams.MATCH_PARENT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY, // ប្រភេទគូរលើ App ដទៃ
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or // មិនរារាំងការចុចលើហ្គេម
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL or
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            PixelFormat.TRANSLUCENT // ធ្វើឱ្យផ្ទៃខាងក្រោយថ្លា (មើលឃើញ App ខាងក្រោម)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // បន្ថែម View ទៅលើអេក្រង់
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    windowManager.addView(overlayView, params)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            override fun onDestroy() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    super.onDestroy()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (::overlayView.isInitialized) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        windowManager.removeView(overlayView)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }